/**
 * GRO-2227 (scope pass for the persistent vault-index cache, GRO-2223): cold-scan baseline for
 * `getIndex()` against vaults generated by `genVault.mjs`. Measures the REAL code path — imports
 * the production live-index map directly; each run goes cold again via `_evictAll()` (drops the
 * in-memory entry and its watcher subscription, exactly what idle eviction does). Runs are
 * interleaved across vaults round-robin so machine noise spreads evenly across sizes.
 *
 * NOTE (post GRO-2228/2229): `getIndex` now consults the persistent cache, but `initIndexCache`
 * is deliberately never called here — the cache dir stays uninjected, every load is a guaranteed
 * miss, and each run stays a TRUE cold scan. Call `initIndexCache` first to bench warm starts.
 *
 * After the timed runs, three supplementary sweeps per vault bound the warm-start floor a
 * persistent cache could reach: walk-only (readdir), walk + stat (the D2 path+mtime+size
 * validation pass), and JSON stringify/parse of the records (the cache round trip).
 *
 * Usage (from the repo root; vaults come from genVault.mjs):
 *   npx tsx --tsconfig desktop/tsconfig.json desktop/e2e/fixtures/benchIndex.ts <vaultDir...> [--runs 5]
 */
import { readdir, stat } from 'node:fs/promises'
import path from 'node:path'
import { _evictAll, getIndex } from '../../src/main/vaultIndex'

const args = process.argv.slice(2)
const runsIdx = args.indexOf('--runs')
const RUNS = runsIdx >= 0 ? Number(args[runsIdx + 1]) : 5
const vaults = args.filter((a, i) => !a.startsWith('--') && !(runsIdx >= 0 && i === runsIdx + 1))
if (vaults.length === 0 || !Number.isInteger(RUNS) || RUNS < 1) {
  console.error('usage: npx tsx --tsconfig desktop/tsconfig.json desktop/e2e/fixtures/benchIndex.ts <vaultDir...> [--runs 5]')
  process.exit(1)
}

const settle = (ms: number) => new Promise((r) => setTimeout(r, ms))
const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]

// Mirrors live.ts `walk` (readdir withFileTypes, dot-entries/node_modules skipped) — the
// live.ts does not export it; this copy exists only to time the walk in isolation.
async function walk(dir: string, out: string[]): Promise<void> {
  const dirents = await readdir(dir, { withFileTypes: true })
  await Promise.all(
    dirents.map(async (e) => {
      if (e.name.startsWith('.') || e.name === 'node_modules') return
      const full = path.join(dir, e.name)
      if (e.isDirectory()) await walk(full, out).catch(() => undefined)
      else if (e.isFile() && /\.(md|markdown)$/i.test(e.name)) out.push(full)
    }),
  )
}

async function statSweep(files: string[]): Promise<void> {
  let next = 0
  const worker = async () => {
    while (next < files.length) await stat(files[next++]).catch(() => undefined)
  }
  await Promise.all(Array.from({ length: Math.min(32, files.length) }, worker))
}

async function main() {
  const results = new Map<string, { notes: number; runs: number[] }>()
  for (const v of vaults) results.set(v, { notes: 0, runs: [] })

  // Round-robin: run r of every vault before run r+1 of any, so drift/noise hits all sizes alike.
  for (let r = 0; r < RUNS; r++) {
    for (const vault of vaults) {
      _evictAll()
      await settle(300) // let the previous run's chokidar close() finish before timing
      const t0 = performance.now()
      const res = await getIndex(vault)
      const ms = performance.now() - t0
      const entry = results.get(vault)!
      entry.notes = res.records.length
      entry.runs.push(ms)
      console.log(`run ${r + 1}/${RUNS}  ${path.basename(vault)}  ${res.records.length} records  ${ms.toFixed(1)} ms`)
    }
  }
  _evictAll()
  await settle(300)

  console.log('\n=== cold full-scan getIndex(root) ===')
  console.log('vault\tnotes\truns (ms)\tmedian (ms)')
  for (const [vault, { notes, runs }] of results) {
    console.log(`${path.basename(vault)}\t${notes}\t${runs.map((x) => x.toFixed(1)).join(', ')}\t${median(runs).toFixed(1)}`)
  }

  console.log('\n=== supplementary: warm-start floor components ===')
  console.log('vault\twalk (ms)\twalk+stat (ms)\tJSON stringify+parse (ms)\tcache size (MB)')
  for (const vault of vaults) {
    const t0 = performance.now()
    const files: string[] = []
    await walk(vault, files)
    const walkMs = performance.now() - t0
    const t1 = performance.now()
    await statSweep(files)
    const statMs = performance.now() - t1
    const res = await getIndex(vault)
    _evictAll()
    const t2 = performance.now()
    const json = JSON.stringify(res.records)
    JSON.parse(json)
    const jsonMs = performance.now() - t2
    console.log(`${path.basename(vault)}\t${walkMs.toFixed(1)}\t${(walkMs + statMs).toFixed(1)}\t${jsonMs.toFixed(1)}\t${(json.length / 1024 / 1024).toFixed(2)}`)
  }
  await settle(300)
  process.exit(0)
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})
